import test from 'node:test';import assert from 'node:assert/strict';
import {authorize,boundedBytes,messages,text,lease} from '../lib/security.mjs';
import {brain,speak,authenticate,transcribe} from '../lib/providers.mjs';
process.env.VOICE_ACCESS_TOKEN='a'.repeat(32);process.env.VOICE_ORIGIN='https://voice.example';process.env.OPENAI_API_KEY='fixture';process.env.DEEPGRAM_API_KEY='fixture';
function request(body={},extra={}){return new Request('https://voice.example/api/brain',{method:'POST',headers:{Origin:process.env.VOICE_ORIGIN,Authorization:`Bearer ${process.env.VOICE_ACCESS_TOKEN}`,'Content-Type':'application/json',...extra},body:JSON.stringify(body)})}
test('auth denies missing, wrong, Unicode credentials and foreign origins',()=>{for(const headers of [{Authorization:''},{Authorization:'Bearer '+'é'.repeat(32)},{Origin:'https://evil.example'}])assert.throws(()=>authorize(request({},headers)));assert.doesNotThrow(()=>authorize(request()))});
test('unconfigured service fails closed',()=>assert.throws(()=>authorize(request(),{})));
test('client system roles, malformed and oversized turns rejected',()=>{for(const value of [null,[],[{role:'system',content:'x'}],[{role:'user',content:'x'.repeat(4097)}]])assert.throws(()=>messages(value));assert.equal(messages([{role:'user',content:'hello'}]).length,1);assert.throws(()=>text(''))});
test('byte and empty frame limits reject hostile streams',async()=>{await assert.rejects(boundedBytes(new ReadableStream({start(c){c.enqueue(new Uint8Array(33));c.close()}}),32));await assert.rejects(boundedBytes(new ReadableStream({pull(c){c.enqueue(new Uint8Array())}})))});
test('body timeout does not await stuck cancellation',async()=>{const start=Date.now();await assert.rejects(boundedBytes(new ReadableStream({cancel(){return new Promise(()=>{})}}),32,20));assert.ok(Date.now()-start<500)});
test('concurrency ceiling and idempotent release',()=>{const releases=Array.from({length:4},()=>lease());assert.throws(()=>lease());releases.forEach(f=>{f();f()});lease()()});
test('all provider routes reject before network for unauthorized callers',async()=>{for(const route of [brain,speak,authenticate,transcribe])assert.equal((await route(request({}, {Authorization:''}),()=>{throw Error('network called')})).status,401)});
test('LLM streams text and propagates consumer cancellation upstream',async()=>{let signal;const mock=()=>({chat:{completions:{create:async(_,opts)=>{signal=opts.signal;return {async *[Symbol.asyncIterator](){yield {choices:[{delta:{content:'hello'}}]};yield {choices:[{delta:{content:' world'}}]}}}}}}});const response=await brain(request({messages:[{role:'user',content:'Hi'}]}),mock);const reader=response.body.getReader();assert.equal(new TextDecoder().decode((await reader.read()).value),'hello');await reader.cancel();assert.ok(signal.aborted)});
test('LLM complete fixture stream',async()=>{const mock=()=>({chat:{completions:{create:async()=>({async *[Symbol.asyncIterator](){yield {choices:[{delta:{content:'hello'}}]}}})}}});assert.equal(await(await brain(request({messages:[{role:'user',content:'Hi'}]}),mock)).text(),'hello')});
test('TTS fixed host, redirects denied, validated body and bounded output',async()=>{let called;const response=await speak(request({content:'Hi'}),async(url,opts)=>{called={url,opts};return new Response(new Uint8Array([1,2,3]))});assert.equal(response.status,200);assert.equal(called.url,'https://api.deepgram.com/v1/speak?model=aura-asteria-en');assert.equal(called.opts.redirect,'error');assert.equal((await response.arrayBuffer()).byteLength,3);assert.equal((await speak(request({content:'Hi'}),async()=>new Response(new Uint8Array(2097153)))).status,413)});
test('temporary key returns grant only, never master key fallback',async()=>{const response=await authenticate(request(),async()=>Response.json({access_token:'temporary'}));assert.deepEqual(await response.json(),{key:'temporary'});assert.equal((await authenticate(request(),async()=>Response.json({access_token:'x'.repeat(2049)}))).status,502)});
test('transcription accepts bounded audio and returns validated transcript',async()=>{const req=new Request('https://voice.example/api/transcribe',{method:'POST',headers:{Origin:process.env.VOICE_ORIGIN,Authorization:`Bearer ${process.env.VOICE_ACCESS_TOKEN}`,'Content-Type':'audio/webm'},body:new Uint8Array([1,2,3])});const response=await transcribe(req,async()=>Response.json({results:{channels:[{alternatives:[{transcript:'Hello voice'}]}]}}));assert.deepEqual(await response.json(),{text:'Hello voice'})});
test('authorization requires Bearer scheme',()=>assert.throws(()=>authorize(request({}, {Authorization:[REDACTED]}))));
test('real OpenAI SDK parses fixture SSE',async()=>{const {default:OpenAI}=await import('openai');const client=()=>new OpenAI({apiKey:'fixture',maxRetries:0,fetch:async()=>new Response('data: '+JSON.stringify({choices:[{delta:{content:'SDK fixture'}}]})+'\n\ndata: [DONE]\n\n',{headers:{'Content-Type':'text/event-stream'}})});const response=await brain(request({messages:[{role:'user',content:'Hi'}]}),client);assert.equal(await response.text(),'SDK fixture')});
test('deadline terminates stalled downstream response and frees capacity',async()=>{let aborted;const mock=()=>({chat:{completions:{create:async(_,opts)=>{aborted=opts.signal;return {[Symbol.asyncIterator](){return {next:()=>new Promise(()=>{})}}}}}}});const response=await brain(request({messages:[{role:'user',content:'Hi'}]}),mock,20);await assert.rejects(response.text());assert.ok(aborted.aborted);const releases=Array.from({length:4},()=>lease());releases.forEach(f=>f())});

import {authenticate} from "../../../lib/providers.mjs";
export const runtime="nodejs";
export const POST=(req:Request)=>authenticate(req);

// SPDX-License-Identifier: MIT
// Security agent — Flags risky MCP grants, leaked secrets, dangerous diffs.

export const SYSTEM_PROMPT = `You scan the harness for the security regressions that matter: MCP grants that widened (Bash(rm:*), shell on, network on, file-write on), .env or token strings that escaped the redaction set, dependency updates that pulled in CVEs, and policy files that drifted from default-deny. Report each finding with a file:line, a severity (HIGH / MEDIUM), and the smallest fix. Never approve a change that widens a permission without a written reason in the PR description. You operate inside the agentic-voice-agent harness; defer destructive actions to the user.`;

export const NAME = 'security';
export const TIER = 'opus' as const;

import {timingSafeEqual} from 'node:crypto';
export class HttpError extends Error {constructor(status){super('Request rejected');this.status=status}}
export function authorize(req, env=process.env) {
 const key=env.VOICE_ACCESS_TOKEN, origin=env.VOICE_ORIGIN;
 if(!key || key.length<32 || !origin) throw new HttpError(503);
 const header=req.headers.get('authorization')||'';
 if(!header.startsWith('Bearer '))throw new HttpError(401);
 const supplied=header.slice(7);
 if(Buffer.byteLength(supplied)!==Buffer.byteLength(key) || !timingSafeEqual(Buffer.from(supplied),Buffer.from(key))) throw new HttpError(401);
 if(req.headers.get('origin')!==origin) throw new HttpError(403);
}
export async function boundedBytes(body, limit=32768, timeout=5000){
 if(!body) throw new HttpError(400);
 const reader=body.getReader();let bytes=0,frames=0;const chunks=[];
 let timer;const expired=new Promise((_,reject)=>{timer=setTimeout(()=>reject(new HttpError(408)),timeout)});
 try{while(true){const {done,value}=await Promise.race([reader.read(),expired]);if(done)break;if(++frames>4096 || (bytes+=value.byteLength)>limit) throw new HttpError(413);chunks.push(value)}return Buffer.concat(chunks,bytes)}finally{clearTimeout(timer);void reader.cancel().catch(()=>{})}
}
export async function readJSON(req){if(!req.headers.get('content-type')?.startsWith('application/json'))throw new HttpError(415);try{return JSON.parse((await boundedBytes(req.body)).toString('utf8'))}catch(e){if(e instanceof HttpError)throw e;throw new HttpError(400)}}
export function messages(value){if(!Array.isArray(value)||value.length<1||value.length>32)throw new HttpError(400);return value.map(m=>{if(!m||!['user','assistant'].includes(m.role)||typeof m.content!=='string'||!m.content.trim()||m.content.length>4096)throw new HttpError(400);return {role:m.role,content:m.content}})}
export function text(value){if(typeof value!=='string'||!value.trim()||value.length>4096)throw new HttpError(400);return value}
let active=0;
export function lease(){if(active>=4)throw new HttpError(429);active++;let released=false;return ()=>{if(!released){released=true;active--}}}
export function failure(e){return Response.json({error:'Request unavailable'},{status:e instanceof HttpError?e.status:502,headers:{'Cache-Control':'no-store'}})}

import {spawn} from 'node:child_process';import assert from 'node:assert/strict';import http from 'node:http';import {fileURLToPath} from 'node:url';
const cwd=fileURLToPath(new URL('../',import.meta.url)),token='smoke-only-'+'x'.repeat(32),origin='http://127.0.0.1:3178';
function request(path='/',auth,method='GET'){return new Promise((resolve,reject)=>{const r=http.request(origin+path,{method,headers:{Origin:origin,Authorization:auth||'','Content-Type':'application/json'}},res=>{let text='';res.on('data',b=>text+=b);res.on('end',()=>resolve({status:res.statusCode,text}))});r.setTimeout(3000,()=>r.destroy(Error('timeout')));r.on('error',reject);r.end(method==='POST'?'{}':undefined)})}
const child=spawn(process.execPath,['node_modules/next/dist/bin/next','start','-H','127.0.0.1','-p','3178'],{cwd,env:{...process.env,VOICE_ACCESS_TOKEN:token,VOICE_ORIGIN:origin,OPENAI_API_KEY:'',DEEPGRAM_API_KEY:''},stdio:['ignore','ignore','inherit']});
try{let ready=false;for(let i=0;i<50;i++){try{if((await request()).status===200){ready=true;break}}catch{}if(child.exitCode!==null)throw Error('Server exited');await new Promise(r=>setTimeout(r,100))}assert.ok(ready,'production server ready');assert.match((await request()).text,/Agentic Voice/);let assertions=1;for(const route of ['brain','speak','authenticate','transcribe']){for(const [auth,status] of [['',401],[`Bearer ${token}`,route==='transcribe'?415:route==='brain'?400:route==='speak'?400:503]]){assert.equal((await request(`/api/${route}`,auth,'POST')).status,status,route);assertions++}}console.log(JSON.stringify({productionHTTPAssertions:assertions,passed:true}))}finally{child.kill('SIGTERM')}

